function initials(name: string): string {
  return name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2);
}

function Brand({ compact = false }: { compact?: boolean }) {
  return (
    <Anchor
      component={Link}
      href="/"
      underline="never"
